<?php
declare(strict_types=1);use Nexus\Application\Administracion\AdministracionService;use Nexus\Domain\Administracion\AdministracionRepository;use Nexus\Domain\ValueObject\Cedula;
require_once __DIR__.'/../proyecto 3ra entrega/src/autoload.php';
final class AdminMemoria implements AdministracionRepository
{public array $reportes=[];public array $catalogos=[];public array $config=[];public function listarReportes():array{return array_values($this->reportes);}public function crearReporte(array $d):int{$id=count($this->reportes)+1;$this->reportes[$id]=array_merge(['id'=>$id,'estado'=>'Pendiente'],$d);return $id;}public function actualizarReporte(int $id,array $d,Cedula $r):bool{if(!isset($this->reportes[$id]))return false;$this->reportes[$id]=array_merge($this->reportes[$id],$d,['responsableId'=>$r->value()]);return true;}public function listarCatalogo(string $t,bool $i):array{return array_values(array_filter($this->catalogos[$t]??[],fn($x)=>$i||$x['activo']));}public function crearCatalogo(string $t,string $n,string $d):int{$id=count($this->catalogos[$t]??[])+1;$this->catalogos[$t][$id]=['id'=>$id,'nombre'=>$n,'descripcion'=>$d,'activo'=>1];return $id;}public function editarCatalogo(string $t,int $id,array $d):bool{if(!isset($this->catalogos[$t][$id]))return false;$this->catalogos[$t][$id]=array_merge($this->catalogos[$t][$id],$d);return true;}public function bajaCatalogo(string $t,int $id):bool{if(empty($this->catalogos[$t][$id]['activo']))return false;$this->catalogos[$t][$id]['activo']=0;return true;}public function configuracion():array{return array_values($this->config);}public function guardarConfiguracion(string $c,string $v,Cedula $u):void{$this->config[$c]=['clave'=>$c,'valor'=>$v,'actualizadoPor'=>$u->value()];}public function historial():array{return [['id'=>1,'fecha_registrado'=>'2026-10-19 10:30:00','etiqueta'=>'Alta','descripcion'=>'Equipo agregado.','referencia'=>'Notebook Dell','tipo'=>'equipo','autor_cedula'=>'57324099','autor_nombre'=>'Jean Ortiz']];}}
function assertA(bool $c,string $m):void{if(!$c)throw new RuntimeException($m);}$r=new AdminMemoria();$s=new AdministracionService($r);$u=new Cedula('57324099');$id=$s->crearReporte(['tipo'=>'Error','contacto'=>'jean@example.test','asunto'=>'Error al guardar','detalle'=>'No se guarda el formulario.']);$s->actualizarReporte($id,'Resuelto','Se corrigió la validación.',$u);assertA($r->reportes[$id]['estado']==='Resuelto','Reporte no resuelto.');$cid=$s->crearCatalogo('servicio_disponible','Instalación de software','Instalación en equipos.');$s->editarCatalogo('servicio_disponible',$cid,'Instalación de software','Descripción actualizada.',true);assertA(count($s->catalogo('servicio_disponible',false))===1,'Catálogo no visible.');$s->bajaCatalogo('servicio_disponible',$cid);assertA(!$s->catalogo('servicio_disponible',false),'Baja de catálogo falló.');$s->guardarConfiguracion('dias_maximos_prestamo','30',$u);$s->guardarConfiguracion('registro_habilitado','1',$u);assertA(count($s->configuracion())===2,'Configuración incompleta.');$h=$s->historial();assertA($h[0]['fecha']==='19/10/2026'&&$h[0]['titulo']==='Alta: Notebook Dell'&&$h[0]['autor']==='Jean Ortiz (57324099)','Historial o autor mal presentado.');echo "OK: 13 comportamientos administrativos verificados.\n";
